#include "core/FactoryPresets.cpp"
#include <cstdio>
#include <iomanip>
#include <iostream>
#include <set>
#include <stdexcept>
using namespace cs80;
int main() {
  std::set<int> allowed{P_drift,P_kbdBrillianceHigh};
  for(int ch=0;ch<2;++ch) {
    for(int id:{CP_lpfCutoff,CP_lpfRes,CP_vA,CP_fA,CP_vD,CP_fD,CP_vR,CP_fR,CP_pan})
      allowed.insert(chParam(ch,id));
    allowed.insert(bodyParam(ch,2));allowed.insert(bodyParam(ch,3));
  }
  int finishes=0,protectedChecks=0,rangeChecks=0,slowChecks=0,sizeChecks=0,roleChecks=0;
  auto require=[](bool x,const std::string& why){if(!x)throw std::runtime_error(why);};
  for(const auto& source:curatedLibrary()) {
    if(source.category=="Init")continue;
    for(int style=0;style<14;++style) {
      auto p=source;original_circuit::finish(p,static_cast<original_circuit::Finish>(style));++finishes;
      require(p.name==source.name && p.category==source.category && p.tags==source.tags,"finish altered identity");
      for(int i=0;i<P_numParams;++i) {
        const auto& def=paramDef(i);++rangeChecks;
        require(std::isfinite(p.values[i]) && p.values[i]>=def.min && p.values[i]<=def.max,"finish produced invalid range: "+source.name+" / "+def.id);
        if(!allowed.count(i)) {++protectedChecks;require(p.values[i]==source.values[i],"finish altered protected control: "+source.name+" / "+def.id);}
      }
      for(int ch=0;ch<2;++ch) {
        const int model=static_cast<int>(source.values[bodyParam(ch,0)]);
        const bool active=source.values[bodyParam(ch,1)]>0.0f;
        const bool percussiveModel=active && ((model>=body::piano && model<=body::bass) || model>=body::bell);
        const bool accent=source.values[chParam(ch,CP_vS)]<=0.10f && source.values[chParam(ch,CP_vD)]<0.65f*source.values[chParam(1-ch,CP_vD)];
        if(percussiveModel || accent) for(int id:{CP_vA,CP_fA}) {
          ++roleChecks;require(p.values[chParam(ch,id)]<=source.values[chParam(ch,id)]+1.0e-7f,"finish stretched struck model/accent attack");
        }
        if(accent) for(int id:{CP_vR,CP_fR}) {
          ++roleChecks;require(p.values[chParam(ch,id)]<=source.values[chParam(ch,id)]*1.025f+1.0e-7f,"finish stretched short accent release");
        }
        if(source.category=="Organ") for(int id:{CP_vA,CP_fA}) {
          ++roleChecks;require(p.values[chParam(ch,id)]<=source.values[chParam(ch,id)]*1.12f+1.0e-7f && p.values[chParam(ch,id)]>=source.values[chParam(ch,id)]*0.88f-1.0e-7f,"finish replaced organ onset");
        }
      }
      if(style==static_cast<int>(original_circuit::Finish::slow) &&
          (source.category=="Keys" || source.category=="Bass" || source.category=="Sequences" || source.category=="Plucked" || source.category=="Bells")) {
        for(int ch=0;ch<2;++ch)for(int id:{CP_vA,CP_fA}){++slowChecks;require(p.values[chParam(ch,id)]==source.values[chParam(ch,id)],"Slow stretched struck attack: "+source.name);}
      }
    }
  }
  const char* tones[2][11]={
    {"Ensemble Strings","Slow Strings","Brass Swell I","Flute","Electric Piano I","Clavichord I","Harpsichord I","Flute Organ 8+4","Guitar I","Funky Pluck I","Funky Clavichord"},
    {"Chamber Strings","PWM Strings","Brass Swell II","Horn Section","Analog Bass","Clavichord II","Harpsichord II","Reed Organ","Guitar II","Funky Pluck II","Funky Pluck I"}
  };
  const auto& original=factoryPresets();
  require(original.size()==222 && curatedLibrary().size()==301,"bank count changed");
  for(int t=0;t<11;++t)for(int row=0;row<2;++row) {
    auto expected=original_circuit::recipe(tones[row][t]);
    original_circuit::finish(expected,row?original_circuit::Finish::amber:original_circuit::Finish::golden);
    const auto& actual=original[2*t+row];
    for(int ch=0;ch<2;++ch) {
      const int from=row?1-ch:ch;
      for(int id:{CP_saw,CP_pulse,CP_sine,CP_noise,CP_pw,CP_pwmDepth,CP_pwmSpeed,CP_feet,CP_initBrill,CP_initLevel,CP_afterBrill,CP_afterLevel})
        require(actual.values[chParam(ch,id)]==expected.values[chParam(from,id)],"tone waveform/footage/expression swap");
      for(int field=0;field<4;++field)require(actual.values[bodyParam(ch,field)]==expected.values[bodyParam(from,field)],"tone body swap");
      ++sizeChecks;require(actual.values[bodySizeParam(ch)]==expected.values[bodySizeParam(from)],"tone size swap");
    }
  }
  std::cout << "{\"finish_cases\":"<<finishes<<",\"protected_parameter_checks\":"<<protectedChecks<<",\"range_checks\":"<<rangeChecks<<",\"struck_slow_attack_checks\":"<<slowChecks<<",\"tone_size_swap_checks\":"<<sizeChecks<<",\"role_protection_checks\":"<<roleChecks<<",\"init_vectors\":[";
  bool first=true;
  for(const auto& p:programLibrary())if(p.category=="Init") {
    if(!first)std::cout<<',';first=false;
    std::cout<<"{\"name\":\""<<p.name<<"\",\"values\":[";
    for(int i=0;i<P_numParams;++i){if(i)std::cout<<',';std::cout<<std::setprecision(9)<<p.values[i];}
    std::cout<<"]}";
  }
  std::cout<<"]}\n";
}
